{
  "name": "MP-285三轴电动位移台",
  "name_en": "MP-285 3-Axis Motorized Stage",
  "manufacturer": "Sutter Instrument",
  "description": "MP-285 是一款三轴电动位移台/微操纵定位系统，可在 X、Y、Z 三个方向进行精密移动。它通常用于显微实验中对样品、探针或光学部件进行微米级定位与重复定位，并配有控制器进行速度、分辨率和运动模式设置。",
  "description_en": "The MP-285 is a 3-axis motorized positioning stage/micromanipulation system that provides precise motion in X, Y, and Z. It is commonly used in microscopy-based laboratory setups to position samples, probes, or optical components with micron-scale control and repeatability, with a controller for setting speed, resolution, and motion mode.",
  "tag_hints": [
    "3-axis motorized stage",
    "microscope positioning",
    "micromanipulation",
    "XYZ translation",
    "serial-controlled stage",
    "micron-scale motion control"
  ],
  "actions": [
    {
      "action_name": "auto-send_command",
      "description": "向位移台发送底层串口命令。",
      "description_en": "Send a low-level serial command to the stage."
    },
    {
      "action_name": "auto-read_response",
      "description": "读取位移台返回的数据响应。",
      "description_en": "Read the data response returned by the stage."
    },
    {
      "action_name": "auto-connect_to_serial",
      "description": "连接位移台控制器的串口通信。",
      "description_en": "Connect to the stage controller over a serial port."
    },
    {
      "action_name": "auto-disconnect_from_serial",
      "description": "断开位移台控制器的串口通信。",
      "description_en": "Disconnect the serial connection to the stage controller."
    },
    {
      "action_name": "auto-move_to_specified_position",
      "description": "将三轴位移台移动到指定的 X、Y、Z 位置。",
      "description_en": "Move the 3-axis stage to the specified X, Y, and Z position."
    },
    {
      "action_name": "auto-set_resolution_and_velocity",
      "description": "设置位移台的运动分辨率和速度。",
      "description_en": "Set the motion resolution and velocity of the stage."
    },
    {
      "action_name": "auto-interrupt_move",
      "description": "中断并停止当前位移运动。",
      "description_en": "Interrupt and stop the current motion."
    },
    {
      "action_name": "auto-set_absolute_mode",
      "description": "将运动模式设为绝对坐标模式。",
      "description_en": "Set motion to absolute positioning mode."
    },
    {
      "action_name": "auto-refresh_display",
      "description": "刷新控制器显示屏。",
      "description_en": "Refresh the controller display."
    },
    {
      "action_name": "auto-reset_controller",
      "description": "重置位移台控制器。",
      "description_en": "Reset the stage controller."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与位移台的通信连接。",
      "description_en": "Close the communication connection to the stage."
    },
    {
      "action_name": "auto-convert_microsteps_to_microns",
      "description": "将微步位移值换算为微米。",
      "description_en": "Convert displacement from microsteps to microns."
    },
    {
      "action_name": "auto-convert_microns_to_microsteps",
      "description": "将微米位移值换算为微步。",
      "description_en": "Convert displacement from microns to microsteps."
    },
    {
      "action_name": "auto-get_current_position",
      "description": "获取当前位移台位置。",
      "description_en": "Get current stage position."
    },
    {
      "action_name": "auto-get_controller_status",
      "description": "获取控制器状态。",
      "description_en": "Get controller status."
    }
  ]
}

